const THEME_KEY='po2-theme';
const THEME_LABEL={auto:'automatique',dark:'sombre',light:'clair'};
const THEME_ICON={auto:'◐',dark:'☾',light:'☀'};
const themeMedia=window.matchMedia('(prefers-color-scheme: dark)');
function applyTheme(mode='auto',announce=false){const normalized=['auto','dark','light'].includes(mode)?mode:'auto';const resolved=normalized==='auto'?(themeMedia.matches?'dark':'light'):normalized;document.documentElement.dataset.themeMode=normalized;document.documentElement.dataset.theme=resolved;localStorage.setItem(THEME_KEY,normalized);const button=document.getElementById('themeButton');const icon=document.getElementById('themeIcon');if(button){button.setAttribute('aria-label',`Thème : ${THEME_LABEL[normalized]}`);button.title=`Thème : ${THEME_LABEL[normalized]} · affichage ${resolved==='dark'?'sombre':'clair'}`}if(icon)icon.textContent=THEME_ICON[normalized];if(announce)toastMessage(`Thème ${THEME_LABEL[normalized]} activé`)}
function cycleTheme(){const current=document.documentElement.dataset.themeMode||'auto';const next={auto:'dark',dark:'light',light:'auto'}[current]||'auto';applyTheme(next,true)}
if(themeMedia.addEventListener)themeMedia.addEventListener('change',()=>{if((document.documentElement.dataset.themeMode||'auto')==='auto')applyTheme('auto')});

