function money(v){return v}
function renderNav(){mainNav.innerHTML=nav.map(section=>`<div class="nav-section"><span class="nav-label">${section.label}</span>${section.items.map(([id,icon,label,count])=>`<button class="nav-item ${state.view===id?'active':''}" data-view="${id}"><span class="nav-icon">${icon}</span><span>${label}</span>${count?`<b class="nav-count ${id==='maintenance'?'warn':''}">${count}</b>`:''}</button>`).join('')}</div>`).join('')}
function renderProfileOptions(){profileSelect.innerHTML=Object.entries(profiles).map(([id,p])=>`<option value="${id}" ${state.profile===id?'selected':''}>${p.label}</option>`).join('')}
function pageHead(eyebrow,title,subtitle,actions=''){return `<div class="page-head"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${subtitle}</p></div><div class="page-actions">${actions}</div></div>`}
function kpiGrid(items){return `<div class="kpi-grid">${items.map(([label,value,sub,trend,trendClass,icon],i)=>`<article class="kpi" style="--accent:${['#1D3150','#425164','#9A6A20','#A84F48'][i]};--tint:${['#E9EDF2','#F0F2F4','#FFF0D9','#FCE8E5'][i]}"><div class="kpi-top"><span>${label}</span><span class="kpi-icon">${icon}</span></div><strong>${value}</strong><small>${sub}</small><small class="trend ${trendClass||''}">${trend}</small></article>`).join('')}</div>`}
function trendChart(){return `<div class="chart-wrap"><svg viewBox="0 0 720 220" role="img" aria-label="Évolution budget, réalisé et atterrissage"><defs><linearGradient id="areaGradient" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#1D3150" stop-opacity=".28"/><stop offset="1" stop-color="#1D3150" stop-opacity="0"/></linearGradient></defs>${[35,80,125,170].map(y=>`<line class="chart-grid" x1="42" x2="700" y1="${y}" y2="${y}"/>`).join('')}<path class="chart-area" d="M45 176 C100 165 120 148 168 151 S250 118 295 122 S380 97 420 103 S502 68 548 76 S625 41 696 49 L696 190 L45 190Z"/><path class="chart-line secondary" d="M45 170 C110 154 145 145 190 137 S280 125 330 113 S430 99 485 84 S590 71 696 58"/><path class="chart-line" d="M45 176 C100 165 120 148 168 151 S250 118 295 122 S380 97 420 103 S502 68 548 76 S625 41 696 49"/>${[[168,151],[295,122],[420,103],[548,76],[696,49]].map(([x,y])=>`<circle class="chart-dot" cx="${x}" cy="${y}" r="4"/>`).join('')}${['Jan','Fév','Mar','Avr','Mai','Juin','Juil','Août','Sep','Oct','Nov','Déc'].map((m,i)=>`<text class="chart-label" x="${45+i*59}" y="210">${m}</text>`).join('')}</svg></div><div class="legend-row"><span><i></i>Réalisé + projection</span><span><i></i>Budget courant</span></div>`}
function priorityList(items){return `<div class="priority-list">${items.map(([label,text,value,sub,kind])=>`<div class="priority-item" data-view="${label==='Factures'||label==='Anomalie'||label==='Échéance'||label==='Import'?'invoices':label==='P3'||label==='Couverture'||label==='PPT'?'technique':'budget'}"><span class="priority-symbol ${kind==='amber'?'amber':kind==='blue'?'blue':''}">${kind==='bad'?'!':kind==='amber'?'↗':'→'}</span><span><strong>${text}</strong><small>${label}</small></span><span class="priority-value"><b>${value}</b><span>${sub}</span></span></div>`).join('')}</div>`}
function cockpitDecisionMap(){const rows=[['Factures','Contrôle facture + matrice comptable','Décider payer / réclamer','invoices','12 à traiter','bad'],['Fluides','Courbes ENEDIS/GRDF + DJU','Recalibrer abonnement ou expliquer dérive','fluids','14 signaux','warn'],['Technique','Criticité CVC + couverture maintenance','Arbitrer P3 / PPT / ordre de service','technique','5 urgences','info'],['Budget','Engagé + facturé + atterrissage','Réallouer ou préparer décision N+1','budget','+286 k€','warn'],['Sites 360°','Patrimoine + contrats + compteurs','Vérifier le contexte avant décision','sites','8 sites','info']];return `<section class="panel decision-map"><div class="panel-head"><div><h2>Chaîne de décision V1</h2><p>Chaque alerte doit dire : source, preuve, responsable et action suivante.</p></div><button class="panel-action" data-action="toast" data-message="Vue décision consolidée simulée">Ouvrir la vue complète →</button></div><div class="decision-lanes">${rows.map(x=>`<button class="decision-lane" data-view="${x[3]}"><span class="decision-dot ${x[5]}"></span><div><strong>${x[0]}</strong><small>${x[1]}</small></div><em>${x[2]}</em><b>${x[4]}</b></button>`).join('')}</div></section>`}
function budgetTable(){return `<table class="budget-table"><thead><tr><th>Opération</th><th>Budget</th><th>Atterrissage</th><th>Écart</th><th>Consommé</th></tr></thead><tbody>${[['231 · Fluides','2,86 M€','2,94 M€','+ 86 k€','83','bad'],['412 · Maintenance','1,74 M€','1,69 M€','– 48 k€','71','good'],['517 · Travaux CVC','1,18 M€','1,26 M€','+ 78 k€','64','bad'],['105 · Patrimoine','824 k€','806 k€','– 18 k€','59','good']].map(r=>`<tr><td>${r[0]}</td><td>${r[1]}</td><td>${r[2]}</td><td class="delta ${r[5]}">${r[3]}</td><td><div class="table-progress"><i style="width:${r[4]}%"></i></div></td></tr>`).join('')}</tbody></table>`}
function renderCockpit(){const p=profiles[state.profile];content.innerHTML=pageHead('Cockpit personnalisé',p.title,p.subtitle,`<div class="segment-control"><button class="active">2026</button><button>2025</button></div><button class="button ghost" data-action="toast" data-message="Export de synthèse préparé (simulation)">↗ Exporter</button>`)+`<div class="context-strip"><span>✦</span><p><b>Lecture recommandée :</b> commencez par les trois sujets prioritaires, puis ouvrez le détail uniquement si une décision est nécessaire.</p><button data-action="toast" data-message="Préférence enregistrée dans le prototype">Ne plus afficher</button></div>`+kpiGrid(p.kpis)+cockpitDecisionMap()+`<div class="dashboard-grid"><div class="stack"><section class="panel"><div class="panel-head"><div><h2>Trajectoire budgétaire 2026</h2><p>Réalisé, engagements et projection consolidée</p></div><button class="panel-action" data-view="budget">Ouvrir le budget →</button></div><div class="panel-body">${trendChart()}</div></section><section class="panel"><div class="panel-head"><div><h2>Budget par numéro d’opération</h2><p>Du global vers la ligne comptable</p></div><button class="panel-action" data-view="budget">Voir toute la matrice →</button></div><div class="panel-body">${budgetTable()}</div></section></div><div class="stack"><section class="panel"><div class="panel-head"><div><h2>À décider maintenant</h2><p>Trié par impact et échéance</p></div><button class="panel-action" data-action="toast" data-message="File personnelle ouverte">Ma file →</button></div><div class="panel-body">${priorityList(p.priorities)}</div></section><section class="panel"><div class="panel-head"><div><h2>Qualité des données</h2><p>La confiance avant le chiffre</p></div><button class="panel-action" data-action="toast" data-message="Détail qualité simulé">Détails →</button></div><div class="panel-body"><div class="info-list"><div class="info-row"><span>Factures et contrôles</span><strong>99 % · à jour</strong></div><div class="mini-progress"><i style="width:99%"></i></div><div class="info-row"><span>Compteurs ENEDIS / GRDF</span><strong>96,8 % · 16 à traiter</strong></div><div class="mini-progress"><i style="width:96.8%"></i></div><div class="info-row"><span>Inventaire CVC</span><strong>88 % · dégradé</strong></div><div class="mini-progress"><i style="width:88%;background:#e9a744"></i></div></div></div></section></div></div>`}

function invoiceWorkflow(){const steps=[['1','Importer','58 fichiers'],['2','Dédoublonner','52 nouvelles · 6 connues'],['3','Parser les lignes','1 284 lignes reconnues'],['4','Associer le contrat','56 automatiques · 2 à revoir'],['5','Imputer','52 complètes · 6 exceptions'],['6','Décider & exporter','16 prêtes finance']];return `<section class="invoice-flow panel"><div class="flow-batch"><div><span class="eyebrow">Dernier lot traité</span><h2>ENGIE · Juin 2026</h2><p>Import annuel autorisé : les factures déjà closes sont reconnues et conservées.</p></div><span class="status ok">Traitement terminé</span></div><div class="invoice-steps">${steps.map((x,i)=>`<div class="invoice-step ${i<5?'done':i===5?'current':''}"><span>${i<5?'✓':x[0]}</span><div><b>${x[1]}</b><small>${x[2]}</small></div></div>`).join('')}</div></section>`}

function accountingMatrixOverview(){return `<section class="panel matrix-overview"><div class="panel-head"><div><span class="eyebrow">Référentiel contractuel</span><h2>Matrices comptables par contrat</h2><p>La facture hérite de la version active ; seules les exceptions sont corrigées par la comptabilité.</p></div><div class="matrix-head-actions"><button class="button ghost" data-action="matrix-import">↑ Importer XLSX</button><button class="button ghost" data-action="matrix-export">↓ Exporter XLSX</button></div></div><div class="matrix-contracts">${accountingMatrices.map(m=>`<article><div class="matrix-contract-top"><span class="supplier-logo ${m.supplier==='DALKIA'?'dalkia':m.supplier==='TotalEnergies'?'total':''}">${m.supplier==='TotalEnergies'?'TE':m.supplier==='DALKIA'?'DK':m.supplier.slice(0,2)}</span><div><strong>${m.supplier}</strong><small>${m.contract}</small></div><span class="status ${m.status==='Active'?'ok':m.status==='À valider'?'warn':'bad'}">${m.status}</span></div><div class="matrix-contract-stats"><span><b>${m.coverage}</b> couverture</span><span><b>${m.rules}</b></span><span class="${m.exceptions==='Aucune'?'good':'warning-text'}"><b>${m.exceptions}</b></span></div><button class="mini-link" data-matrix="${m.id}">Éditer la matrice →</button></article>`).join('')}</div><div class="matrix-xlsx-note"><span>↕</span><p><b>Aller-retour XLSX sécurisé :</b> export avec identifiants stables → modification hors plateforme → aperçu des différences → validation explicite. Aucun réimport n’écrase directement une version active.</p></div></section>`}

function invoiceMatrixStatus(inv){if(inv.supplier==='EDF')return ['Validée','ok'];if(inv.supplier==='ENGIE')return ['Proposée','info'];if(inv.supplier==='TotalEnergies')return ['À compléter','warn'];return ['À arbitrer','bad']}

function renderInvoices(){content.innerHTML=pageHead('Factures & décisions','Importer, contrôler, imputer, décider.','Une chaîne unique relie la facture à son contrat, sa matrice comptable et la transmission aux finances.',`<button class="button ghost" data-action="toast" data-message="Rapport d’import ouvert (simulation)">Rapports d’import</button><button class="button dark" data-action="toast" data-message="Zone d’import simulée : aucun fichier envoyé">＋ Importer des factures</button>`)+invoiceWorkflow()+`<div class="kpi-grid">${[['Nouvelles','12','184 320 €','depuis le dernier import','neutral','＋'],['Imputation complète','52','sur 58 factures','','✓'],['Exceptions comptables','6','4 règles · 2 contrats','down','!'],['Transmises aux finances','16','172 480 €','ce mois','','→']].map((x,i)=>kpiGrid([x]).replace('kpi-grid','kpi-single')).join('')}</div>`+accountingMatrixOverview()+`<div class="toolbar-row"><label class="filter-search">⌕<input id="invoiceSearch" placeholder="Numéro, fournisseur, site ou marché"></label><select class="filter-select"><option>Tous les fournisseurs</option><option>ENGIE</option><option>EDF</option><option>TotalEnergies</option><option>DALKIA</option></select><select class="filter-select"><option>Toutes les imputations</option><option>Validée</option><option>Proposée</option><option>À compléter</option><option>À arbitrer</option></select></div><section class="panel table-panel"><table class="data-table"><thead><tr><th>Fournisseur / facture</th><th>Site</th><th>Marché</th><th>Montant TTC</th><th>Émission</th><th>Matrice</th><th>Décision</th><th></th></tr></thead><tbody id="invoiceRows">${invoiceRows(invoices)}</tbody></table></section>`}

function invoiceRows(rows){return rows.map(inv=>{const matrix=invoiceMatrixStatus(inv);return `<tr data-invoice="${inv.id}"><td><div class="supplier"><span class="supplier-logo ${inv.logo}">${inv.supplier==='TotalEnergies'?'TE':inv.supplier==='DALKIA'?'DK':inv.supplier.slice(0,2).toUpperCase()}</span><span><b>${inv.supplier}</b><small>${inv.id}</small></span></div></td><td>${inv.site}</td><td>${inv.market}</td><td class="amount">${inv.amount}</td><td>${inv.date}</td><td><span class="status ${matrix[1]}">${matrix[0]}</span></td><td><span class="status ${inv.status}">${inv.statusLabel}</span></td><td class="table-link">Ouvrir →</td></tr>`}).join('')}

function renderSites(){if(!state.site){content.innerHTML=pageHead('Sites 360°','Vue générale des sites et bâtiments.','Commencez par le portefeuille, filtrez les priorités, puis ouvrez la fiche détaillée d’un site.',`<button class="button ghost" data-action="toast" data-message="Export portefeuille préparé (simulation)">↗ Exporter la liste</button>`)+`<div class="kpi-grid">${[['Sites','118','203 bâtiments','référentiel actif','','⌂'],['Qualité fiable','92 %','109 sites','9 à fiabiliser','neutral','◎'],['Sites à surveiller','8','couverture ou données','actions prioritaires','down','!'],['Budget analysé','8,42 M€','par opération et antenne','exercice 2026','','€']].map(x=>kpiGrid([x]).replace('kpi-grid','kpi-single')).join('')}</div><div class="toolbar-row"><label class="filter-search">⌕<input placeholder="Nom, adresse, antenne ou usage"></label><select class="filter-select"><option>Tous les usages</option><option>Enseignement</option><option>Sport</option><option>Culture</option><option>Administration</option></select><select class="filter-select"><option>Toutes les qualités</option><option>À fiabiliser</option><option>Fiable</option></select></div><section class="panel table-panel"><table class="data-table"><thead><tr><th>Site / bâtiment</th><th>Usage</th><th>Qualité</th><th>Budget</th><th>Fluides</th><th>Équipements critiques</th><th></th></tr></thead><tbody>${sites.map(x=>`<tr data-site="${x.id}"><td><b>${x.name}</b><small style="display:block;color:var(--muted);margin-top:3px">${x.address}</small></td><td>${x.type}</td><td><span class="status ${parseInt(x.quality)>=95?'ok':'warn'}">${x.quality}</span></td><td class="amount">${x.budget}</td><td>${x.energy}</td><td><b>${x.critical}</b></td><td class="table-link">Ouvrir →</td></tr>`).join('')}</tbody></table></section>`;return}const s=sites.find(x=>x.id===state.site)||sites[0];content.innerHTML=pageHead('Site 360°','Le site comme porte d’entrée.','Une fiche transversale pour comprendre patrimoine, fluides, contrats, technique et budget.',`<button class="button ghost" data-action="back-sites">← Tous les sites</button><button class="button ghost" data-action="toast" data-message="Fiche site exportée (simulation)">↗ Exporter la fiche</button>`)+`<div class="site-layout"><section class="panel site-list"><label class="site-search">⌕<input placeholder="Rechercher un site"></label>${sites.map(x=>`<article class="site-card ${x.id===s.id?'active':''}" data-site="${x.id}"><strong>${x.name}</strong><span>${x.address}</span><span class="site-card-footer"><em class="quality-dot">Qualité ${x.quality}</em><b>${x.critical} critiques</b></span></article>`).join('')}</section><section class="panel"><div class="site-detail-head"><span class="eyebrow">Site 360°</span><h2>${s.name}</h2><p>${s.address}</p><div class="site-tags"><span class="tag">${s.type}</span><span class="tag">Propriétaire</span><span class="tag">Qualité ${s.quality}</span></div></div><div class="site-tabs">${[['synthese','Synthèse'],['fluides','Fluides'],['contrats','Contrats'],['technique','Technique'],['budget','Budget & PPT'],['documents','Documents']].map(([id,label])=>`<button class="${state.siteTab===id?'active':''}" data-site-tab="${id}">${label}</button>`).join('')}</div><div class="site-content">${siteTabContent(s)}</div></section></div>`}
function siteTabContent(s){if(state.siteTab==='fluides')return `<div class="site-metrics"><div class="site-metric"><span>Électricité 2026</span><strong>184 MWh</strong></div><div class="site-metric"><span>Gaz corrigé DJU</span><strong>312 MWh</strong></div><div class="site-metric"><span>Évolution</span><strong>${s.energy}</strong></div><div class="site-metric"><span>Compteurs</span><strong>${s.meters}</strong></div></div><div class="subpanel"><h3>Profil de consommation mensuel</h3>${trendChart()}</div>`;if(state.siteTab==='technique')return `<div class="site-metrics"><div class="site-metric"><span>Équipements</span><strong>${s.equipment}</strong></div><div class="site-metric"><span>Critiques</span><strong>${s.critical}</strong></div><div class="site-metric"><span>Couverture</span><strong>91 %</strong></div><div class="site-metric"><span>Besoin travaux</span><strong>${s.budget}</strong></div></div><div class="site-columns"><div class="subpanel"><h3>Équipements à surveiller</h3>${equipmentRows()}</div><div class="subpanel"><h3>Prochaines échéances</h3><div class="info-list"><div class="info-row"><span>Contrôle étanchéité F-Gaz</span><strong>12 j</strong></div><div class="info-row"><span>Visite préventive chaudière</span><strong>28 j</strong></div><div class="info-row"><span>Revue annuelle PPT</span><strong>64 j</strong></div></div></div></div>`;if(state.siteTab==='budget')return `<div class="site-metrics"><div class="site-metric"><span>Budget courant</span><strong>${s.budget}</strong></div><div class="site-metric"><span>Engagé</span><strong>71 %</strong></div><div class="site-metric"><span>Atterrissage</span><strong>+ 4,2 %</strong></div><div class="site-metric"><span>PPT 5 ans</span><strong>486 k€</strong></div></div><div class="subpanel"><h3>Trajectoire du site</h3>${budgetTable()}</div>`;if(state.siteTab==='contrats')return `<div class="site-columns"><div class="subpanel"><h3>Contrats actifs</h3><div class="info-list"><div class="info-row"><span>DALKIA P1</span><strong>Couvert · 2024–2032</strong></div><div class="info-row"><span>DALKIA P2/P3</span><strong>Partiel · 2024–2032</strong></div><div class="info-row"><span>SPIE</span><strong>Hors périmètre</strong></div></div></div><div class="subpanel"><h3>Contacts entreprise</h3><div class="info-list"><div class="info-row"><span>Référent principal</span><strong>Contact DALKIA actif</strong></div><div class="info-row"><span>Escalade</span><strong>Responsable de secteur</strong></div><div class="info-row"><span>Dernière vérification</span><strong>18 juin 2026</strong></div></div></div></div>`;if(state.siteTab==='documents')return `<div class="empty-state"><span>▱</span><h2>Documents et chronologie</h2><p>Contrats, factures, rapports d’intervention et décisions seront présentés par date, source et version active.</p><button class="button ghost" data-action="toast" data-message="Explorateur documentaire simulé">Voir les documents</button></div>`;return `<div class="site-metrics"><div class="site-metric"><span>Budget opérationnel</span><strong>${s.budget}</strong></div><div class="site-metric"><span>Évolution fluides</span><strong>${s.energy}</strong></div><div class="site-metric"><span>Équipements CVC</span><strong>${s.equipment}</strong></div><div class="site-metric"><span>Criticité élevée</span><strong>${s.critical}</strong></div></div><div class="site-columns"><div class="subpanel"><h3>Identité et occupation</h3><div class="info-list"><div class="info-row"><span>Usage principal</span><strong>${s.type}</strong></div><div class="info-row"><span>Référent bâtiment</span><strong>Service Patrimoine</strong></div><div class="info-row"><span>Occupation</span><strong>Lun–Ven · 8h–19h</strong></div><div class="info-row"><span>Surface utile</span><strong>2 840 m²</strong></div></div></div><div class="subpanel"><h3>À surveiller</h3>${equipmentRows()}</div></div>`}
function siteDecisionFeed(s){const rows=[['Facture à décider',s.name.includes('Beaux')?'TotalEnergies TG-88412':'ENGIE EN-260621-18','Contrôle + matrice comptable','invoices','warn'],['Abonnement à vérifier',s.meters,'Courbe de charge / profil distributeur','fluids','info'],['Maintenance',s.critical+' équipements critiques','Couverture DALKIA / SPIE et action P3','technique','bad'],['Budget site',s.budget,'Atterrissage et arbitrage annuel','budget','info']];return `<div class="site-decision-feed"><h3>Décisions reliées au site</h3>${rows.map(x=>`<button data-view="${x[3]}"><span class="status ${x[4]}">${x[0]}</span><strong>${x[1]}</strong><small>Preuve : ${x[2]}</small></button>`).join('')}</div>`}
function equipmentRows(){return [['Chaudière gaz 02','Mise en service 2004','8,7','bad'],['CTA salle principale','Maintenance à jour','6,1',''],['Groupe froid 01','F-Gaz dans 12 jours','7,4','bad']].map(x=>`<div class="equipment-row"><span class="equipment-icon">⚙</span><span><strong>${x[0]}</strong><small>${x[1]}</small></span><b class="score ${x[3]}">${x[2]}/10</b></div>`).join('')}

function fluidTrendChart(){return `<div class="fluid-chart-wrap"><svg viewBox="0 0 820 300" role="img" aria-label="Consommations réelles, référence corrigée et atterrissage"><defs><linearGradient id="fluidActual" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#1D3150" stop-opacity=".28"/><stop offset="1" stop-color="#1D3150" stop-opacity="0"/></linearGradient><linearGradient id="fluidBand" x1="0" y1="0" x2="1" y2="0"><stop offset="0" stop-color="#74B44A" stop-opacity=".08"/><stop offset="1" stop-color="#74B44A" stop-opacity=".28"/></linearGradient></defs>${[48,100,152,204,256].map(y=>`<line x1="44" x2="792" y1="${y}" y2="${y}" class="chart-grid"/>`).join('')}<path d="M44 244 C97 222 125 211 165 216 S246 177 294 188 S376 145 422 159 S505 112 548 126 L548 269 L44 269Z" fill="url(#fluidActual)"/><path d="M548 106 C600 83 643 79 690 64 S756 50 792 36 L792 101 C748 112 705 123 661 132 S594 144 548 159Z" fill="url(#fluidBand)"/><path d="M44 230 C100 211 135 199 184 199 S266 174 311 170 S395 140 446 143 S516 119 548 126 S634 99 690 82 S755 61 792 56" class="fluid-reference"/><path d="M44 244 C97 222 125 211 165 216 S246 177 294 188 S376 145 422 159 S505 112 548 126" class="fluid-actual"/><path d="M548 126 C600 111 640 103 690 94 S754 78 792 68" class="fluid-forecast"/>${[[165,216],[294,188],[422,159],[548,126]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="4" class="fluid-dot"/>`).join('')}<line x1="548" x2="548" y1="30" y2="270" class="fluid-today"/><text x="556" y="43" class="fluid-note">Aujourd’hui</text>${['Jan','Fév','Mar','Avr','Mai','Juin','Juil','Août','Sep','Oct','Nov','Déc'].map((m,i)=>`<text x="${44+i*68}" y="292" class="chart-label">${m}</text>`).join('')}</svg></div><div class="fluid-legend"><span><i class="actual"></i>Réel distributeurs</span><span><i class="reference"></i>N-1 corrigée climat</span><span><i class="forecast"></i>Prévision centrale</span><span><i class="band"></i>Fourchette basse/haute</span></div>`}
function fluidTabs(){return `<div class="fluid-tabs">${[['all','Tous les fluides',''],['electricity','Électricité','ENEDIS'],['gas','Gaz','GRDF'],['water','Eau','À construire']].map(([id,label,badge])=>`<button class="${state.fluidTab===id?'active':''}" data-fluid-tab="${id}"><span>${id==='electricity'?'ϟ':id==='gas'?'♨':id==='water'?'◌':'⌁'}</span><b>${label}</b>${badge?`<em class="${id==='water'?'future':''}">${badge}</em>`:''}</button>`).join('')}</div>`}
function fluidWaterState(){return `<section class="fluid-water panel"><div class="water-orbit"><span>◌</span></div><div><span class="eyebrow">Prochain fluide</span><h2>L’eau est visible, mais aucune donnée n’est inventée.</h2><p>L’architecture prévoit les compteurs d’eau, les volumes en m³, la couverture, les dérives et l’atterrissage. L’écran sera activé dès qu’un export ou un connecteur distributeur réel sera disponible.</p><div class="water-requirements"><span>Référentiel compteurs</span><span>Historique distributeur</span><span>Rattachement aux sites</span><span>Tarifs contractuels</span></div><button class="button ghost" data-action="toast" data-message="Dépendances Eau affichées (simulation)">Voir les dépendances</button></div></section>`}
function fluidKpis(){const sets={all:[['Consommation observée','18,4 GWh','487 compteurs couverts','Électricité + gaz','⌁'],['Évolution corrigée','– 6,8 %','vs N-1 à climat comparable','Tendance favorable','↘'],['Atterrissage central','19,1 GWh','18,7 à 19,6 GWh','Hypothèses visibles','◎'],['Impact estimé','2,94 M€','+ 48 k€ vs budget','Prix contractuels','€']],electricity:[['Électricité observée','11,8 GWh','436 PRM couverts','Source ENEDIS','ϟ'],['Évolution corrigée','– 4,2 %','chauffage + froid','Hiver / été','↘'],['Atterrissage central','12,2 GWh','11,9 à 12,5 GWh','Scénario 2026','◎'],['Courbes de charge','412 actives','14 dérives prioritaires','Pas 30 minutes','⌁']],gas:[['Gaz observé','6,2 GWh','51 PCE couverts','Source GRDF','♨'],['Évolution corrigée','– 8,7 %','vs N-1 corrigée DJU','Hiver favorable','↘'],['Atterrissage central','6,9 GWh','6,7 à 7,1 GWh','Scénario 2026','◎'],['Couverture','94,1 %','3 PCE à rattacher','Collecte mensuelle','◉']]};return sets[state.fluidTab]||sets.all}

function fluidForecast(){const sets={all:{source:'ENEDIS au 23 juin · GRDF au 21 juin',coverage:'96,8 %',central:'19,1 GWh',range:'18,7 — 19,6 GWh',realized:'9,6 GWh',remaining:'9,5 GWh',climate:'DJU chauffage + froid',euros:'2,94 M€'},electricity:{source:'ENEDIS au 23 juin',coverage:'97,8 %',central:'12,2 GWh',range:'11,9 — 12,5 GWh',realized:'6,1 GWh',remaining:'6,1 GWh',climate:'DJU chauffage + froid',euros:'1,88 M€'},gas:{source:'GRDF au 21 juin',coverage:'94,1 %',central:'6,9 GWh',range:'6,7 — 7,1 GWh',realized:'3,5 GWh',remaining:'3,4 GWh',climate:'DJU chauffage',euros:'1,06 M€'}};return sets[state.fluidTab]||sets.all}
function fluidSiteTable(){const rows=[['Centre sportif Fonquerne','Sport','428 MWh','+ 18,4 %','92 %','Talon nocturne + pointe','fonquerne','bad'],['Hôtel de Ville','Administration','312 MWh','+ 6,1 %','98 %','Week-end atypique','hotel-ville','warn'],['École des Beaux-Arts','Enseignement','246 MWh','– 7,2 %','96 %','Aucune dérive forte','beaux-arts','ok'],['Médiathèque Mitterrand','Culture','221 MWh','– 4,1 %','99 %','Profil régulier','mitterrand','ok']];return `<table class="data-table fluid-table"><thead><tr><th>Site</th><th>Usage</th><th>Observé</th><th>Évolution</th><th>Couverture</th><th>Signal principal</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr data-site="${r[6]}"><td><b>${r[0]}</b></td><td>${r[1]}</td><td class="amount">${r[2]}</td><td class="delta ${r[7]==='bad'?'bad':'good'}">${r[3]}</td><td><span class="status ${parseInt(r[4])>=95?'ok':'warn'}">${r[4]}</span></td><td>${r[5]}</td><td class="table-link">Analyser →</td></tr>`).join('')}</tbody></table>`}

function fluidSubscriptions(){return `<section class="panel subscription-panel"><div class="panel-head"><div><span class="eyebrow">Contrats sous surveillance</span><h2>Abonnements à recalibrer</h2><p>Mesures distributeurs → paramètres contractuels → recommandation explicable.</p></div><button class="panel-action" data-action="toast" data-message="48 abonnements classés par gain, risque et confiance">Ouvrir la file complète →</button></div><div class="subscription-summary"><div><strong>48</strong><span>abonnements à étudier</span></div><div><strong>6</strong><span>risques de dépassement</span></div><div><strong>58 k€</strong><span>économie électrique estimée</span></div><div><strong>30 min</strong><span>pas des courbes ENEDIS</span></div></div><div class="subscription-table-wrap"><table class="data-table subscription-table"><thead><tr><th>Site / abonnement</th><th>Mesure</th><th>Contrat</th><th>Actuel</th><th>Recommandation</th><th>Impact</th><th>Confiance</th><th></th></tr></thead><tbody>${subscriptionAnalyses.map(r=>`<tr><td><b>${r.site}</b><small>${r.meter}</small></td><td>${r.source}</td><td>${r.supplier}</td><td>${r.current}</td><td><b>${r.recommendation}</b><small>${r.change}</small></td><td class="amount">${r.potential}</td><td><span class="status ${r.confidence.startsWith('Haute')?'ok':r.kind==='water'?'info':'warn'}">${r.confidence.split(' · ')[0]}</span></td><td><button class="mini-link" data-subscription="${r.id}">Voir le calcul →</button></td></tr>`).join('')}</tbody></table></div><p class="subscription-note"><b>Méthode :</b> électricité sur courbes de charge et puissance souscrite ; gaz sur profil GRDF, CAR et contrat TotalEnergies ; eau selon télérelève et structure tarifaire disponible.</p></section>`}
function renderFluids(){const periodActions=`<div class="segment-control"><button class="active">2026</button><button>2025</button></div><button class="button ghost" data-action="toast" data-message="Synthèse Fluides exportée (simulation)">↗ Exporter</button>`;let html=pageHead('Pilotage des consommations','Fluides & consommations','Une lecture percutante des données distributeurs, du patrimoine jusqu’au compteur.',periodActions)+fluidTabs();if(state.fluidTab==='water'){content.innerHTML=html+fluidWaterState();return}const kpis=fluidKpis();const forecast=fluidForecast();html+=`<div class="fluid-source-strip"><span class="live-dot"></span><b>Sources distributeurs</b><span>${forecast.source}</span><em>Couverture ${forecast.coverage}</em></div><div class="fluid-kpis">${kpis.map((x,i)=>`<article><span class="fluid-kpi-icon">${x[4]}</span><small>${x[0]}</small><strong>${x[1]}</strong><p>${x[2]}</p><em class="${i===1?'good':i===3?'warn':''}">${x[3]}</em></article>`).join('')}</div><div class="fluid-main-grid"><section class="panel fluid-chart-panel"><div class="panel-head"><div><span class="eyebrow">Trajectoire 2026</span><h2>Réel, climat et atterrissage</h2><p>Mensuel · consommation physique distributeurs uniquement</p></div><div class="fluid-chart-controls"><button class="active">Mensuel</button><button>Journalier</button><button data-action="toast" data-message="Comparaison N-1 brute activable dans le futur écran">N-1 corrigée</button></div></div><div class="panel-body">${fluidTrendChart()}</div></section><aside class="panel forecast-card"><div class="forecast-head"><span>◎</span><div><small>Scénario central</small><strong>${forecast.central}</strong></div></div><div class="forecast-range"><span>Fourchette</span><b>${forecast.range}</b></div><div class="forecast-formula"><span><i style="width:72%"></i></span><div><b>${forecast.realized}</b><small>réalisé distributeurs</small></div><strong>＋</strong><div><b>${forecast.remaining}</b><small>reste estimé</small></div></div><div class="info-list"><div class="info-row"><span>Hypothèse climatique</span><strong>${forecast.climate}</strong></div><div class="info-row"><span>Impact financier estimé</span><strong>${forecast.euros}</strong></div><div class="info-row"><span>Dernière version</span><strong>Auto · 24 juin</strong></div></div><button class="button mint" data-action="toast" data-message="Éditeur de scénario métier ouvert (simulation)">Créer un scénario corrigé</button></aside></div><div class="fluid-season-grid"><section class="panel season-card winter"><div class="season-icon">❄</div><div><span class="eyebrow">Hiver · chauffage</span><h3>– 9,4 % à climat comparable</h3><p>Gaz et électricité thermosensible · oct. à avr.</p></div><div class="season-score"><b>86</b><small>kWh / DJU</small></div></section><section class="panel season-card summer"><div class="season-icon">☀</div><div><span class="eyebrow">Été · froid</span><h3>+ 3,8 % de besoin électrique</h3><p>Climatisation · mai à sept. · DJU froid</p></div><div class="season-score"><b>12</b><small>sites à suivre</small></div></section></div><div class="fluid-bottom-grid"><section class="panel"><div class="panel-head"><div><h2>Dérives prioritaires</h2><p>Consommations journalières et courbes de charge 30 min</p></div><button class="panel-action" data-action="toast" data-message="File des dérives ouverte (simulation)">Voir les 14 signaux →</button></div><div class="panel-body"><div class="fluid-alert"><span class="alert-rank bad">1</span><div><b>Talon nocturne persistant</b><small>Centre sportif Fonquerne · PRM 300024… · depuis 21 jours</small></div><strong>+ 42 MWh/an</strong></div><div class="fluid-alert"><span class="alert-rank warn">2</span><div><b>Consommation le week-end</b><small>Hôtel de Ville · profil samedi supérieur de 34 %</small></div><strong>+ 11 MWh/an</strong></div><div class="fluid-alert"><span class="alert-rank info">3</span><div><b>Rupture de profil gaz</b><small>École Michelet · PCE non rattaché à confirmer</small></div><strong>Confiance 72 %</strong></div></div></section><section class="panel quality-card"><div class="panel-head"><div><h2>Confiance dans la lecture</h2><p>Une valeur sans source n’est pas une décision.</p></div></div><div class="panel-body"><div class="quality-ring"><b>96,8 %</b><span>couverture</span></div><div class="info-list"><div class="info-row"><span>ENEDIS journalier</span><strong>436 / 446 PRM</strong></div><div class="info-row"><span>Courbes de charge</span><strong>412 actives</strong></div><div class="info-row"><span>GRDF mensuel</span><strong>48 / 51 PCE</strong></div><div class="info-row"><span>Non rattachés</span><strong class="warning-text">16 compteurs</strong></div></div></div></section></div>${fluidSubscriptions()}<section class="panel table-panel fluid-sites-panel"><div class="panel-head"><div><h2>Sites à regarder en premier</h2><p>Classés par dérive, impact estimé et qualité des données.</p></div><button class="panel-action" data-view="sites">Voir les 118 sites →</button></div>${fluidSiteTable()}</section>`;content.innerHTML=html}
function renderComing(){const meta={fluids:['Fluides','Consommations, DJU et atterrissages','La maquette détaillée de ce domaine viendra après validation du cockpit.'],contracts:['Marchés & contrats','Versions, périmètres et contacts','La structure sera commune aux fournisseurs et prestataires, sans gommer leurs spécificités.'],maintenance:['Maintenance','Couverture et exécution','DALKIA et SPIE seront reliés au patrimoine et aux équipements.'],technique:['Technique & PPT','État CVC, criticité et travaux','Inventaire, contrôles, devis P3 et programme à cinq ans.'],budget:['Budget & finances','De la matrice comptable à l’atterrissage','Cette surface s’appuie sur le numéro d’opération et la matrice analytique DALKIA, sans synchronisation CIRIL.'],patrimoine:['Patrimoine','Sites, bâtiments et locaux','Le référentiel maître et ses rapprochements.'],admin:['Administration','Profils, qualité et référentiels','Droits, sources, imports et audit.']}[state.view];content.innerHTML=pageHead(meta[0],meta[1],meta[2])+`<section class="panel empty-state"><span>✦</span><h2>Parcours identifié dans la V1</h2><p>Ce premier jet privilégie le cockpit, les factures et la fiche Site 360°. Cette section sera dessinée à partir des mêmes composants après votre retour.</p><button class="button ghost" data-view="cockpit">Revenir au cockpit</button></section>`}
function render(){renderNav();renderProfileOptions();if(state.view==='cockpit')renderCockpit();else if(state.view==='invoices')renderInvoices();else if(state.view==='sites')renderSites();else if(state.view==='fluids')renderFluids();else renderComing();content.focus({preventScroll:true});sidebar.classList.remove('open')}

function matrixSelect(value,options){const values=[value,...options.filter(x=>x!==value)];return `<select class="matrix-select">${values.map(x=>`<option>${x}</option>`).join('')}</select>`}

function openAccountingMatrix(id){const matrix=accountingMatrices.find(x=>x.id===id);if(!matrix)return;state.drawer='matrix:'+id;drawer.classList.remove('wide');drawer.classList.add('matrix-wide');drawerContent.innerHTML=`<div class="drawer-top matrix-drawer-head"><button class="drawer-close" data-action="close-drawer">×</button><span class="eyebrow">Matrice comptable contractuelle</span><h2>${matrix.supplier} · ${matrix.contract}</h2><p>${matrix.version} · données simulées à confirmer par la comptabilité</p></div><div class="drawer-body matrix-detail"><div class="drawer-kpis"><div><span>Couverture automatique</span><b>${matrix.coverage}</b></div><div><span>Règles actives</span><b>${matrix.rules}</b></div><div><span>Exceptions</span><b>${matrix.exceptions}</b></div></div><div class="matrix-version-bar"><div><span class="status ${matrix.status==='Active'?'ok':matrix.status==='À valider'?'warn':'bad'}">${matrix.status}</span><div><strong>Version utilisée pour les nouveaux imports</strong><small>Une facture conserve toujours la version appliquée au moment de sa validation.</small></div></div><button class="button ghost" data-action="toast" data-message="Nouvelle version brouillon créée">Créer une nouvelle version</button></div><div class="matrix-editor-wrap"><table class="matrix-editor"><thead><tr><th>Composante parsée</th><th>Périmètre</th><th>Service</th><th>Fonction</th><th>Nature</th><th>Opération</th><th>Antenne</th><th>Ventilation</th><th>État</th></tr></thead><tbody>${matrix.rows.map((r,i)=>`<tr><td><input class="matrix-input" value="${r[0]}"></td><td>${matrixSelect(r[1],['Tous sites','Selon site','Selon contrat/site','Éclairage public'])}</td><td>${matrixSelect(r[2],['Bâtiments','Finances','Voirie','Maintenance','Technique'])}</td><td><input class="matrix-code" value="${r[3]}"></td><td><input class="matrix-code" value="${r[4]}"></td><td>${matrixSelect(r[5],['231','412','517','À valider'])}</td><td>${matrixSelect(r[6],['Fluides','Éclairage','Technique','Patrimoine'])}</td><td><input class="matrix-percent" value="${r[7]}"></td><td><span class="status ${r[8]==='ok'?'ok':'warn'}">${r[8]==='ok'?'Complet':'À confirmer'}</span></td></tr>`).join('')}</tbody></table></div><div class="matrix-rules"><div><span>✓</span><p><b>Contrôles avant validation :</b> champs obligatoires, dates d’effet, ventilation à 100 %, cohérence site/opération et absence de doublon de règle.</p></div><div><span>↕</span><p><b>Réimport XLSX :</b> les lignes sont rapprochées par <code>contract_id + version + rule_id</code>. Un écran de différences précède toute création de version.</p></div></div></div><div class="drawer-actions matrix-actions"><button class="button ghost" data-action="matrix-export">↓ Exporter XLSX</button><button class="button ghost" data-action="matrix-import">↑ Importer les corrections</button><button class="button mint" data-action="matrix-save">Enregistrer le brouillon</button></div>`;drawer.classList.add('open');drawerBackdrop.classList.add('open');drawer.setAttribute('aria-hidden','false')}

function subscriptionCurve(item){if(item.kind==='water')return `<div class="calibration-empty"><span>◌</span><b>Aucune courbe exploitable</b><p>Des index mensuels ne permettent ni de calculer le débit de pointe ni de vérifier le diamètre du compteur.</p></div>`;const gas=item.kind==='gas';const currentY=item.verdict.includes('Surdimensionné')?62:96;const targetY=82;const path=gas?'M30 146 C88 132 112 93 164 104 S240 58 292 72 S368 124 422 112 S502 68 566 84':'M30 150 C70 142 92 108 126 120 S178 78 210 98 S264 132 302 108 S350 54 392 76 S448 138 486 114 S532 84 566 96';return `<div class="calibration-chart"><svg viewBox="0 0 600 205" role="img" aria-label="${gas?'Profil de consommation mensuel':'Courbe de charge journalière'}"><line x1="30" x2="570" y1="48" y2="48"/><line x1="30" x2="570" y1="96" y2="96"/><line x1="30" x2="570" y1="144" y2="144"/><path d="${path}" class="calibration-load"/><line x1="30" x2="570" y1="${currentY}" y2="${currentY}" class="calibration-current"/><line x1="30" x2="570" y1="${targetY}" y2="${targetY}" class="calibration-target"/><text x="38" y="${currentY-6}" class="current-label">contrat actuel</text><text x="38" y="${targetY-5}" class="target-label">niveau recommandé</text>${(gas?['Jan','Mar','Mai','Juil','Sep','Nov']:['00h','04h','08h','12h','16h','20h']).map((x,i)=>`<text x="${30+i*106}" y="194">${x}</text>`).join('')}</svg><div class="calibration-legend"><span><i class="load"></i>Mesure ${item.source}</span><span><i class="current"></i>Paramètre actuel</span><span><i class="target"></i>Recommandation</span></div></div>`}

function openSubscription(id){drawer.classList.remove('matrix-wide');const item=subscriptionAnalyses.find(x=>x.id===id);if(!item)return;state.drawer='subscription:'+id;drawer.classList.add('wide');drawerContent.innerHTML=`<div class="drawer-top"><button class="drawer-close" data-action="close-drawer">×</button><span class="eyebrow">Calibrage d’abonnement</span><h2>${item.site}</h2><p>${item.scope} · ${item.meter}</p></div><div class="drawer-body subscription-detail"><div class="subscription-verdict ${item.verdict.includes('Surdimensionné')?'good':item.kind==='water'?'neutral':'warn'}"><span>${item.kind==='water'?'◌':item.verdict.includes('Surdimensionné')?'↘':'!'}</span><div><small>Diagnostic</small><strong>${item.verdict}</strong><p>${item.kind==='electricity'?item.current+' actuellement → '+item.recommendation+' recommandés':item.recommendation}</p></div><b>${item.potential}</b></div><div class="drawer-kpis"><div><span>Abonnement actuel</span><b>${item.current}</b></div><div><span>Mesure de référence</span><b>${item.reference}</b></div><div><span>Recommandation</span><b>${item.recommendation}</b></div></div><section class="subpanel calibration-panel"><div class="calibration-title"><div><h3>${item.kind==='gas'?'Profil annuel corrigé':'Courbe utilisée pour le calcul'}</h3><p>Source ${item.source} · fraîcheur ${item.freshness}</p></div><span class="status ${item.confidence.startsWith('Haute')?'ok':item.kind==='water'?'info':'warn'}">${item.confidence}</span></div>${subscriptionCurve(item)}</section><h3>Construction de la recommandation</h3><div class="control-list">${item.method.map(x=>`<div class="control-row"><span class="control-check ${x[2]==='warn'?'warn':''}">${x[2]==='warn'?'!':'✓'}</span><span><strong>${x[0]}</strong><small>${x[1]}</small></span></div>`).join('')}</div><div class="subpanel calibration-proof"><h3>Contrat, source et décision</h3><div class="info-list"><div class="info-row"><span>Distributeur / mesure</span><strong>${item.source}</strong></div><div class="info-row"><span>Fournisseur / contrat</span><strong>${item.supplier} · ${item.contract}</strong></div><div class="info-row"><span>Couverture analysée</span><strong>${item.coverage}</strong></div><div class="info-row"><span>Risque identifié</span><strong>${item.risk}</strong></div></div></div></div><div class="drawer-actions"><button class="button ghost" data-action="toast" data-message="Abonnement ajouté à la file d’instruction">Marquer à instruire</button><button class="button mint" data-action="toast" data-message="Brouillon de demande fournisseur préparé">Préparer la demande fournisseur</button></div>`;drawer.classList.add('open');drawerBackdrop.classList.add('open');drawer.setAttribute('aria-hidden','false')}

function openInvoice(id){drawer.classList.remove('wide','matrix-wide');const inv=invoices.find(x=>x.id===id);if(!inv)return;state.drawer=id;drawerContent.innerHTML=`<div class="drawer-top"><button class="drawer-close" data-action="close-drawer">×</button><span class="eyebrow">Dossier facture</span><h2>${inv.supplier} · ${inv.id}</h2><p>${inv.site} · ${inv.market}</p></div><div class="drawer-body"><div class="drawer-kpis"><div><span>Montant TTC</span><b>${inv.amount}</b></div><div><span>Échéance</span><b>${inv.due}</b></div><div><span>Statut</span><b>${inv.statusLabel}</b></div></div><div class="context-strip"><span>${inv.status==='bad'?'!':'✓'}</span><p><b>Verdict :</b> ${inv.issue}</p></div><h3>Trace de contrôle</h3><div class="control-list">${[['Fourniture','BPU contractuel et période','3 842,16 €','ok'],['Acheminement','Barème réglementaire daté','2 406,72 €','ok'],['Taxes et contributions',inv.status==='bad'?'CTA à expliquer':'Référentiels en vigueur','1 126,40 €',inv.status==='bad'?'warn':'ok'],['TVA','Assiette et taux vérifiés','1 366,90 €','ok']].map(x=>`<div class="control-row"><span class="control-check ${x[3]==='warn'?'warn':''}">${x[3]==='warn'?'!':'✓'}</span><span><strong>${x[0]}</strong><small>${x[1]}</small></span><b>${x[2]}</b></div>`).join('')}</div><div class="subpanel" style="margin-top:16px"><h3>Décision et preuve</h3><div class="info-list"><div class="info-row"><span>Contrat / version</span><strong>${inv.market} · actif</strong></div><div class="info-row"><span>Données de consommation</span><strong>Couverture 98 %</strong></div><div class="info-row"><span>Dernier recalcul</span><strong>Aujourd’hui · 09:42</strong></div></div></div></div><div class="drawer-actions"><button class="button ghost" data-action="claim" data-id="${inv.id}">Préparer une réclamation</button><button class="button mint" data-action="approve" data-id="${inv.id}">Valider le contrôle</button></div>`;drawer.classList.add('open');drawerBackdrop.classList.add('open');drawer.setAttribute('aria-hidden','false')}
function closeDrawer(){drawer.classList.remove('open','wide','matrix-wide');drawerBackdrop.classList.remove('open');drawer.setAttribute('aria-hidden','true');state.drawer=null}
function toastMessage(message){toast.textContent=message;toast.classList.add('show');clearTimeout(toast._timer);toast._timer=setTimeout(()=>toast.classList.remove('show'),2400)}
function openSearch(){searchDialog.showModal();commandSearch.value='';renderSearch('');setTimeout(()=>commandSearch.focus(),0)}
function renderSearch(q){q=q.toLowerCase().trim();const rows=searchIndex.filter(x=>!q||x[2].toLowerCase().includes(q)||x[3].toLowerCase().includes(q));searchResults.innerHTML=rows.map((x,i)=>`<div class="search-result" data-result="${i}" data-view="${x[4]}" data-target="${x[5]}"><span>${x[1]}</span><div><strong>${x[2]}</strong><small>${x[3]}</small></div><em>${x[0]}</em></div>`).join('')||`<div class="empty-state" style="min-height:180px"><span>⌕</span><p>Aucun résultat dans les données simulées.</p></div>`}
document.addEventListener('click',e=>{const view=e.target.closest('[data-view]');if(view){state.view=view.dataset.view;if(view.classList.contains('nav-item')&&state.view==='sites')state.site=null;render();return}const matrix=e.target.closest('[data-matrix]');if(matrix){openAccountingMatrix(matrix.dataset.matrix);return}const subscription=e.target.closest('[data-subscription]');if(subscription){openSubscription(subscription.dataset.subscription);return}const inv=e.target.closest('[data-invoice]');if(inv){openInvoice(inv.dataset.invoice);return}const site=e.target.closest('[data-site]');if(site){state.site=site.dataset.site;state.view='sites';render();return}const tab=e.target.closest('[data-site-tab]');if(tab){state.siteTab=tab.dataset.siteTab;render();return}const fluidTab=e.target.closest('[data-fluid-tab]');if(fluidTab){state.fluidTab=fluidTab.dataset.fluidTab;render();return}const action=e.target.closest('[data-action]');if(!action)return;const a=action.dataset.action;if(a==='open-about')aboutDialog.showModal();if(a==='open-search')openSearch();if(a==='close-drawer')closeDrawer();if(a==='back-sites'){state.site=null;render();}if(a==='theme')cycleTheme();if(a==='notifications')toastMessage('4 notifications simulées dans votre file');if(a==='matrix-export')toastMessage('Classeur XLSX versionné préparé (simulation)');if(a==='matrix-import')toastMessage('Aperçu des différences XLSX ouvert (simulation)');if(a==='matrix-save')toastMessage('Brouillon de matrice enregistré (simulation)');if(a==='toast')toastMessage(action.dataset.message||'Action simulée');if(a==='approve'){const item=invoices.find(x=>x.id===action.dataset.id);item.status='info';item.statusLabel='Transmise';item.issue='Contrôle validé et prêt pour la liaison finance';closeDrawer();render();toastMessage('Facture validée dans le prototype');}if(a==='claim'){toastMessage('Brouillon de réclamation préparé');}});
drawerBackdrop.addEventListener('click',closeDrawer);menuButton.addEventListener('click',()=>sidebar.classList.toggle('open'));profileSelect.addEventListener('change',e=>{state.profile=e.target.value;state.view='cockpit';render();toastMessage('Cockpit adapté au profil '+profiles[state.profile].label)});commandSearch.addEventListener('input',e=>renderSearch(e.target.value));searchResults.addEventListener('click',e=>{const row=e.target.closest('[data-result]');if(!row)return;searchDialog.close();state.view=row.dataset.view;if(row.dataset.view==='sites')state.site=row.dataset.target;render();if(row.dataset.view==='invoices'&&row.dataset.target)openInvoice(row.dataset.target)});document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch()}if(e.key==='Escape'&&state.drawer)closeDrawer()});document.addEventListener('input',e=>{if(e.target.id==='invoiceSearch'){const q=e.target.value.toLowerCase();const rows=invoices.filter(x=>Object.values(x).join(' ').toLowerCase().includes(q));invoiceRowsEl=document.querySelector('#invoiceRows');if(invoiceRowsEl)invoiceRowsEl.innerHTML=invoiceRows(rows)}});
applyTheme(document.documentElement.dataset.themeMode||'auto');
render();
